---
/**
 * Pure board arithmetic: grouping issues into columns and computing what a
 * drop produces.
 *
 * The board is optimistic — the card has to land under the cursor before the
 * server action resolves — so the "what does the board look like after this
 * move?" question must be answerable synchronously and identically on both
 * sides. Keeping it here (rather than inside the drag handler) is what makes
 * that testable.
 */
import { BOARD_STATUS_ORDER } from "../issue/issue-tone";
import type { IssueId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueStatus } from "@/types/issue";

/** Sort inside a column: urgent work first, then oldest — the queue people
 *  actually want to see. */
const PRIORITY_WEIGHT: Readonly<Record<Issue["priority"], number>> = {
  urgent: 0,
  high: 1,
  medium: 2,
  low: 3,
  none: 4,
};

export function compareBoardIssues(a: Issue, b: Issue): number {
  const byPriority = PRIORITY_WEIGHT[a.priority] - PRIORITY_WEIGHT[b.priority];
  if (byPriority !== 0) return byPriority;
  return a.createdAt.localeCompare(b.createdAt);
}

/** Groups a flat issue list into one column per status, in workflow order. */
export function buildBoardColumns(
  issues: readonly Issue[],
): readonly IssueBoardColumn[] {
  const byStatus = new Map<IssueStatus, Issue[]>();
  for (const status of BOARD_STATUS_ORDER) byStatus.set(status, []);

  for (const issue of issues) {
    const bucket = byStatus.get(issue.status);
    if (bucket === undefined) continue;
    bucket.push(issue);
  }

  return BOARD_STATUS_ORDER.map((status) => {
    const bucket = (byStatus.get(status) ?? []).sort(compareBoardIssues);
    return { status, issues: bucket, total: bucket.length };
  });
}

/** Re-orders arbitrary columns into the canonical workflow order. */
export function orderColumns(
  columns: readonly IssueBoardColumn[],
): readonly IssueBoardColumn[] {
  return [...columns].sort(
    (a, b) =>
      BOARD_STATUS_ORDER.indexOf(a.status) -
      BOARD_STATUS_ORDER.indexOf(b.status),
  );
}

export function findIssue(
  columns: readonly IssueBoardColumn[],
  issueId: IssueId,
): Issue | null {
  for (const column of columns) {
    const found = column.issues.find((issue) => issue.id === issueId);
    if (found !== undefined) return found;
  }
  return null;
}

/**
 * Moves one issue to `toStatus` at `toIndex`, returning fresh columns.
 *
 * `toIndex` is clamped: dropping past the end of a column is a normal gesture,
 * not an error, and a drop onto the column the card already sits in is a
 * re-order rather than a status change.
 */
export function moveIssueInColumns(
  columns: readonly IssueBoardColumn[],
  issueId: IssueId,
  toStatus: IssueStatus,
  toIndex: number,
): readonly IssueBoardColumn[] {
  const moving = findIssue(columns, issueId);
  if (moving === null) return columns;

  const moved: Issue = { ...moving, status: toStatus };

  return columns.map((column) => {
    if (column.status === toStatus) {
      const without = column.issues.filter((issue) => issue.id !== issueId);
      const index = Math.max(0, Math.min(toIndex, without.length));
      const next = [
        ...without.slice(0, index),
        moved,
        ...without.slice(index),
      ];
      return { status: column.status, issues: next, total: next.length };
    }

    if (column.issues.some((issue) => issue.id === issueId)) {
      const next = column.issues.filter((issue) => issue.id !== issueId);
      return { status: column.status, issues: next, total: next.length };
    }

    return column;
  });
}
---
import { describe, expect, it } from "vitest";
import {
  buildBoardColumns,
  compareBoardIssues,
  findIssue,
  moveIssueInColumns,
  orderColumns,
} from "@/components/domain/board/board-model";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

const ORG_ID = "org_1" as OrgId;
const PROJECT_ID = "prj_1" as ProjectId;
const AUTHOR_ID = "usr_1" as UserId;

function issue(
  id: string,
  status: IssueStatus,
  priority: IssuePriority = "none",
  createdAt = "2026-01-01T00:00:00.000Z",
): Issue {
  return {
    id: id as IssueId,
    orgId: ORG_ID,
    projectId: PROJECT_ID,
    number: Number(id.replace(/\D/g, "")) || 1,
    title: `Issue ${id}`,
    description: null,
    status,
    priority,
    authorId: AUTHOR_ID,
    assigneeId: null,
    parentId: null,
    estimate: null,
    dueAt: null,
    startedAt: null,
    completedAt: null,
    labelIds: [],
    archivedAt: null,
    createdAt: toIsoTimestamp(createdAt),
    updatedAt: toIsoTimestamp(createdAt),
  };
}

describe("board-model/buildBoardColumns", () => {
  it("creates one column per status in workflow order", () => {
    const columns = buildBoardColumns([issue("i1", "todo")]);
    expect(columns.map((column) => column.status)).toEqual([
      "backlog",
      "todo",
      "in_progress",
      "in_review",
      "done",
      "canceled",
    ]);
  });

  it("counts each column and keeps empty ones", () => {
    const columns = buildBoardColumns([
      issue("i1", "todo"),
      issue("i2", "todo"),
      issue("i3", "done"),
    ]);
    const byStatus = new Map(columns.map((c) => [c.status, c]));
    expect(byStatus.get("todo")?.total).toBe(2);
    expect(byStatus.get("done")?.total).toBe(1);
    expect(byStatus.get("backlog")?.issues).toEqual([]);
  });

  it("orders a column by priority first, then age", () => {
    const columns = buildBoardColumns([
      issue("i1", "todo", "low", "2026-01-01T00:00:00.000Z"),
      issue("i2", "todo", "urgent", "2026-02-01T00:00:00.000Z"),
      issue("i3", "todo", "low", "2025-12-01T00:00:00.000Z"),
    ]);
    const todo = columns.find((column) => column.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i2", "i3", "i1"]);
  });
});

describe("board-model/compareBoardIssues", () => {
  it("ranks urgent above high", () => {
    expect(
      compareBoardIssues(issue("a", "todo", "urgent"), issue("b", "todo", "high")),
    ).toBeLessThan(0);
  });
});

describe("board-model/moveIssueInColumns", () => {
  const columns = buildBoardColumns([
    issue("i1", "todo"),
    issue("i2", "todo"),
    issue("i3", "in_progress"),
  ]);

  it("moves an issue between columns and rewrites its status", () => {
    const next = moveIssueInColumns(columns, "i1" as IssueId, "in_progress", 0);
    const todo = next.find((c) => c.status === "todo");
    const inProgress = next.find((c) => c.status === "in_progress");

    expect(todo?.issues.map((i) => i.id)).toEqual(["i2"]);
    expect(todo?.total).toBe(1);
    expect(inProgress?.issues.map((i) => i.id)).toEqual(["i1", "i3"]);
    expect(findIssue(next, "i1" as IssueId)?.status).toBe("in_progress");
  });

  it("clamps an index past the end of the target column", () => {
    const next = moveIssueInColumns(columns, "i3" as IssueId, "todo", 99);
    const todo = next.find((c) => c.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i1", "i2", "i3"]);
  });

  it("re-orders within the same column without duplicating the card", () => {
    const next = moveIssueInColumns(columns, "i2" as IssueId, "todo", 0);
    const todo = next.find((c) => c.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i2", "i1"]);
    expect(todo?.total).toBe(2);
  });

  it("leaves the board untouched for an unknown issue", () => {
    expect(moveIssueInColumns(columns, "nope" as IssueId, "done", 0)).toBe(
      columns,
    );
  });
});

describe("board-model/orderColumns", () => {
  it("restores workflow order from an arbitrary arrangement", () => {
    const scrambled = [
      { status: "done" as IssueStatus, issues: [], total: 0 },
      { status: "backlog" as IssueStatus, issues: [], total: 0 },
    ];
    expect(orderColumns(scrambled).map((c) => c.status)).toEqual([
      "backlog",
      "done",
    ]);
  });
});

